import {contentPages} from './content.js';
const $ = (selector) => document.querySelector(selector);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = (value, digits=0) => Number.isFinite(Number(value)) && value !== null ? Number(value).toLocaleString('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits}) : '—';
const pct = value => `${number(Number(value)*100,1)}%`;
const colors = {'Low':'#5cab7e','Moderate':'#e8c756','High':'#e79a49','Very High':'#d76b56'};
const priorities = Object.keys(colors);
const paths = {overview:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',map:'m3 6 6-3 6 3 6-3v15l-6 3-6-3-6 3ZM9 3v15M15 6v15',hotspots:'M12 3C9 8 5 9 5 14a7 7 0 0 0 14 0c0-3-2-6-4-7 0 3-2 4-2 4S11 7 12 3Z',methodology:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4ZM13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',about:'M12 11v6M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',search:'m21 21-5-5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',tree:'m12 2 6 7h-3l5 7h-6v6h-4v-6H4l5-7H6Z',arrow:'M5 12h14m-5-5 5 5-5 5',area:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5M8 8h8v8H8Z'};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.about}"/></svg>`;
const route = location.pathname.split('/').pop()?.replace('.html','') || 'index';
const page = route === 'index' ? 'overview' : route;
const nav = [['overview','Overview','index.html'],['map','Explore map','map.html'],['hotspots','Hotspot clusters','hotspots.html'],['methodology','Methodology','methodology.html'],['about','About the project','about.html']];
$('#navigation').innerHTML = nav.map(([key,label,url])=>`<a href="${url}" class="${page===key?'active':''}" ${page===key?'aria-current="page"':''}>${icon(key)}${label}</a>`).join('');
$('#route-name').textContent = nav.find(n=>n[0]===page)?.[1] || 'Overview';
let data, map, layerGroup, selectedLayer, filtered=[], currentPage=1;
const state = {query:'',priority:'All',reliability:'All',source:'All',cluster:null,selected:null};
const heading = (title,description,eyebrow='BENGALURU, KARNATAKA') => `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${description}</p></div><div class="date-badge">27 Jan – 03 May 2026<small>7 analysis dates · Research snapshot</small></div></div>`;
const badge = (label) => `<span class="pill ${esc(label.toLowerCase().replaceAll(' ','-'))}">${esc(label)}</span>`;
const note = () => `<div class="data-note">${icon('about')}<span>Land surface temperature (LST) is different from air temperature. Priorities are relative to this study grid; tree counts are scenario estimates. <a href="methodology.html#interpretation">Read the methodology</a>.</span></div>`;
function statistics(){const s=data.project_summary;return `<section class="stats" aria-label="Study summary">${[
 ['Analysis grid',number(s.study_area_km2),'km²','1,320 cells · approximately 1 km each','area'],
 ['High + very high priority',number(s.high_and_very_high_cells),'km²','25% of the analysis grid','hotspots'],
 ['Connected hotspots',number(s.hotspot_clusters),'clusters','Adjacent high-priority cells','map'],
 ['Scenario tree estimate','1.36','million',`${number(s.scenario_based_trees)} trees · 30 m² canopy / tree`,'tree']
 ].map(([label,value,unit,sub,ico],i)=>`<article class="stat ${i===3?'stat-accent':''}"><div class="stat-label">${label}${icon(ico)}</div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${sub}</div></article>`).join('')}</section>`}
function filters(){return `<div class="filters"><label class="search-field">${icon('search')}<span class="sr-only">Search locality, suburb or grid ID</span><input id="search" type="search" placeholder="Search locality or grid…" autocomplete="off"></label><label class="sr-only" for="priority-select">Cooling priority</label><select id="priority-select"><option value="All">All priorities</option>${priorities.map(p=>`<option>${p}</option>`).join('')}</select><button id="toggle-filters" class="mobile-filter-toggle" aria-expanded="false" aria-controls="extra-filters">More filters</button><div class="filter-row" id="extra-filters"><label class="sr-only" for="reliability">Planning reliability</label><select id="reliability"><option value="All">All reliability</option>${['Strong','Moderate','Limited','Model Only'].map(p=>`<option>${p}</option>`).join('')}</select><label class="sr-only" for="source">Data source</label><select id="source"><option value="All">All sources</option>${['Reliable Multi-Date Observation','Limited Observation + V5','V5 Prediction Only'].map(p=>`<option>${p}</option>`).join('')}</select><button class="reset" id="reset">Reset filters</button></div></div>`}
function overview(){return heading(page==='map'?'Explore the heat grid.':'Cooling priorities, mapped.','Explore persistent surface heat and where cooling can make a difference.')+(page==='overview'?statistics():'')+`<div id="cluster-context"></div><section class="map-layout"><div class="panel map-panel"><div class="panel-title"><div><h2>Cooling priority map</h2><p id="result-count" role="status">1,320 analysis cells</p></div>${page==='overview'?'<a href="map.html">Explore grid '+icon('arrow')+'</a>':''}</div>${filters()}<div class="map-actions" role="group" aria-label="Map navigation"><button id="zoom-in" aria-label="Zoom in">+ Zoom in</button><button id="zoom-out" aria-label="Zoom out">− Zoom out</button><button id="fit-results">Fit results</button></div><div class="map-canvas" id="map" role="region" aria-label="Bengaluru cooling priority map. Grid cells are also available in the results table below." tabindex="0"></div><div class="map-note"><div class="legend">${priorities.map(p=>`<span><i class="swatch" style="--color:${colors[p]}"></i>${p}</span>`).join('')}</div><span>Fainter cells: model-only</span></div></div><aside class="rail" id="insights" aria-label="Study insights"></aside></section>${note()}<section class="panel table-panel" id="grid-results"><div class="panel-title"><div><h2>Grid results</h2><p>Inspect a cell for its cooling recommendation and evidence.</p></div></div><div class="table-scroll"><table class="grid-table"><caption class="sr-only">Filtered analysis cells</caption><thead><tr><th>Locality / Grid ID</th><th>Priority</th><th>Median LST</th><th>Reliability</th><th>Scenario trees</th></tr></thead><tbody id="grid-rows"></tbody></table></div><div class="pagination" id="pagination"></div></section>`}
function insights(){const counts=Object.fromEntries(priorities.map(p=>[p,filtered.filter(g=>g.Final_Cooling_Priority===p).length]));const total=filtered.length;const high=counts.High+counts['Very High'];$('#insights').innerHTML=`<section class="panel"><div class="panel-title"><h2>${total===1320?'Study':'Filtered'} priorities</h2></div><div class="rail-content"><div class="big-share">${total?number(high/total*100,0):'0'}% <small>high + very high</small></div><p class="fineprint">${number(high)} of ${number(total)} matching grid cells</p><div class="stacked" aria-hidden="true">${priorities.map(p=>`<span style="--color:${colors[p]};--width:${total?counts[p]/total*100:0}%"></span>`).join('')}</div>${priorities.map(p=>`<div class="distribution-row"><span><i class="swatch" style="--color:${colors[p]}"></i>${p}</span><span>${number(counts[p])}</span><span>${total?number(counts[p]/total*100):0}%</span></div>`).join('')}<p class="fineprint" style="margin-top:16px">The highest 25% of study heat scores define the High and Very High classes.</p></div></section><section class="panel"><div class="panel-title"><h2>Top planning hotspots</h2></div><div class="rail-content"><ol class="rank-list">${data.hotspot_clusters.slice(0,3).map(c=>`<li><a class="rank-link" href="map.html?cluster=${c.Cluster_ID}"><span class="rank-number">0${c.Planning_Rank}</span><span><strong>${esc(c.Dominant_Locality)}</strong><small>${number(c.Cluster_Area_km2)} km² · ${number(c.Mean_Median_LST,2)} °C mean median</small></span><span class="score">${number(c.Planning_Significance_Score,1)}</span></a></li>`).join('')}</ol><a class="fineprint" href="hotspots.html">View all 73 clusters →</a></div></section>`}
function matches(g){const q=state.query.trim().toLowerCase();return (!q||[g.Area_Name,g.Suburb,g.Grid_ID].some(v=>String(v??'').toLowerCase().includes(q)))&&(state.priority==='All'||g.Final_Cooling_Priority===state.priority)&&(state.reliability==='All'||g.Planning_Reliability===state.reliability)&&(state.source==='All'||g.Data_Source===state.source)&&(!state.cluster||data.cluster_membership[g.Grid_ID]===state.cluster)}
function gridBounds(rows){return rows.map(g=>[[g.South_Latitude,g.West_Longitude],[g.North_Latitude,g.East_Longitude]]).flat()}
function cellStyle(g){return {color:'#f4f5df',weight:.6,opacity:.65,fillColor:colors[g.Final_Cooling_Priority],fillOpacity:g.Planning_Reliability==='Model Only'?.42:.67}}
function updateFilters(fit=true){filtered=data.grid_data.filter(matches);currentPage=1;state.selected=null;selectedLayer=null;$('#result-count').textContent=`${number(filtered.length)} of 1,320 cells · ${filtered.length?number(filtered.reduce((n,g)=>n+g.Final_Median_LST,0)/filtered.length,2)+' °C mean median LST':'No matching cells'}`;document.querySelectorAll('[data-priority]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.priority===state.priority)));if(layerGroup){layerGroup.clearLayers();for(const g of filtered){const layer=L.rectangle([[g.South_Latitude,g.West_Longitude],[g.North_Latitude,g.East_Longitude]],cellStyle(g));layer.bindTooltip(`${esc(g.Area_Name||'Unnamed locality')} · ${esc(g.Final_Cooling_Priority)} · ${number(g.Final_Median_LST,2)} °C`,{sticky:true});layer.on('click',()=>selectCell(g.Grid_ID,false,layer));layerGroup.addLayer(layer);layer.gridId=g.Grid_ID;}if(fit&&filtered.length)map.fitBounds(gridBounds(filtered),{padding:[22,22],maxZoom:13,animate:false});}insights();renderRows()}
function renderRows(){const size=10;const pages=Math.max(1,Math.ceil(filtered.length/size));const rows=filtered.slice((currentPage-1)*size,currentPage*size);$('#grid-rows').innerHTML=rows.length?rows.map(g=>`<tr><td><button class="cell-link" data-cell="${esc(g.Grid_ID)}">${esc(g.Area_Name||'Unnamed locality')}</button><small>${esc(g.Grid_ID)}</small></td><td data-label="Priority">${badge(g.Final_Cooling_Priority)}</td><td data-label="Median LST">${number(g.Final_Median_LST,2)} °C</td><td data-label="Reliability">${esc(g.Planning_Reliability)}</td><td data-label="Scenario trees">${number(g.Approx_Trees_To_Plant)}</td></tr>`).join(''):'<tr><td class="empty" colspan="5">No cells match these filters. Try another locality or reset the filters.</td></tr>';$('#pagination').innerHTML=`<span>${filtered.length?`${(currentPage-1)*size+1}–${Math.min(currentPage*size,filtered.length)} of ${number(filtered.length)} cells`:'0 cells'}</span><div><button id="previous" ${currentPage===1?'disabled':''}>Previous</button><span>${currentPage} / ${pages}</span><button id="next" ${currentPage===pages?'disabled':''}>Next</button></div>`;$('#previous').onclick=()=>{currentPage--;renderRows()};$('#next').onclick=()=>{currentPage++;renderRows()};document.querySelectorAll('[data-cell]').forEach(b=>b.onclick=()=>selectCell(b.dataset.cell,true))}
function cellEvidence(g){
  const v=data.cell_indicators?.[g.Grid_ID];
  if(!v)return '<p class="fineprint">Environmental indicators are unavailable for this cell.</p>';
  const rows=[['NDVI · Landsat',number(v.Final_L_NDVI,3)],['NDVI · Sentinel-2',number(v.Final_S2_NDVI,3)],['NDBI · built-up index',number(v.Median_NDBI,3)],['NDWI · water index',number(v.Median_NDWI,3)],['Albedo · reflectivity',number(v.Final_Albedo,3)],['Distance to water',`${number(v.Final_Distance_To_Water/1000,2)} km`],['Elevation',`${number(v.Elevation,1)} m`]];
  const parts=[['Heat intensity','Heat_Intensity_Score',30],['Hot frequency','Hot_Frequency_Score',25],['Very-hot frequency','Very_Hot_Frequency_Score',10],['Low tree probability','Low_Tree_Score',15],['Built probability','Built_Score',10],['Distance to water','Water_Distance_Score',5],['Low albedo','Low_Albedo_Score',5]];
  return `<section class="cell-evidence"><h3>Environmental indicators</h3><dl class="detail-grid">${rows.map(([k,value])=>`<div><dt>${k}</dt><dd>${value}</dd></div>`).join('')}</dl><p class="fineprint">NDVI describes vegetation, NDBI built-up characteristics, and NDWI water characteristics. These are unitless indices, not land-cover percentages.</p><p class="fineprint">NDVI, albedo and distance to water follow this cell’s final hybrid source. NDBI and NDWI are medians from the complete-grid series across the 7 analysis dates; they may use different samples from this cell’s temperature summary.</p><h3>What makes up the heat score?</h3><p class="fineprint">Points out of 100 from the saved scoring formula. Each bar shows points relative to that factor’s maximum.</p><dl class="score-parts">${parts.map(([label,key,max])=>`<div><dt>${label}</dt><dd>${number(v[key]*max,2)} <span>/ ${max}</span></dd><progress value="${v[key]*max}" max="${max}" aria-label="${label} contribution">${number(v[key]*max,2)} of ${max}</progress></div>`).join('')}</dl><p class="fineprint">Contributions add up to the heat score before rounding. NDVI, NDBI and NDWI enter the temperature model, but are not separate terms in this score. These indicators do not measure each feature’s causal effect on temperature.</p></section>`;
}
function selectCell(id,focus=false,layer){const g=filtered.find(g=>g.Grid_ID===id);if(!g)throw new Error('Grid cell is not in the current results.');if(selectedLayer){const previous=data.grid_data.find(c=>c.Grid_ID===selectedLayer.gridId);selectedLayer.setStyle(cellStyle(previous))}state.selected=id;selectedLayer=layer||layerGroup?.getLayers().find(l=>l.gridId===id);selectedLayer?.setStyle({color:'#183e30',weight:3,opacity:1,fillOpacity:.85});selectedLayer?.bringToFront();if(focus&&map)map.fitBounds(gridBounds([g]),{maxZoom:13,animate:false,padding:[35,35]});$('#insights').innerHTML=`<section class="panel"><div class="panel-title"><span class="eyebrow" style="margin:0">CELL ${esc(g.Grid_ID)}</span><button id="close-detail" class="close-detail" aria-label="Close cell details">×</button></div><div class="rail-content"><button id="back-to-map" class="mobile-back">Back to map ↑</button><h2 class="detail-title" tabindex="-1">${esc(g.Area_Name||'Unnamed locality')}</h2>${badge(g.Final_Cooling_Priority)}<div class="detail-number">${number(g.Final_Median_LST,2)}<small> °C</small></div><div class="detail-label">Median estimated surface temperature</div><dl class="detail-grid">${[['Maximum LST',`${number(g.Final_Max_LST,2)} °C`],['Heat score',`${number(g.Hybrid_Heat_Score,2)} / 100`],['Hot frequency',pct(g.Final_Hot_Frequency)],['Very-hot frequency',pct(g.Final_Very_Hot_Frequency)],['Tree probability',pct(g.Final_Tree_Probability)],['Built probability',pct(g.Final_Built_Probability)],['Suggested greening',`${number(g.Suggested_Greening_Percent,2)}%`],['Scenario trees',number(g.Approx_Trees_To_Plant)],['Trees / hectare',number(g.Trees_Per_Hectare,2)],['Tree cooling share',pct(g.Tree_Cooling_Share)]].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}<div class="full"><dt>Recommended intervention</dt><dd>${esc(g.Recommended_Intervention)}</dd></div><div class="full"><dt>Planning reliability</dt><dd>${esc(g.Planning_Reliability)}</dd></div><div class="full"><dt>Data source · original export label</dt><dd>${esc(g.Data_Source)}</dd></div></dl>${cellEvidence(g)}<div class="callout">Scenario assumes 30 m² of mature canopy per tree. Planting feasibility needs a field survey.</div><p class="fineprint" style="margin-top:13px">Source labels describe observation support. Displayed temperatures are model-derived. Locality names label cell centres.</p></div></section>`;$('#back-to-map').onclick=()=>{$('#map').scrollIntoView({block:'center'});$('#map').focus({preventScroll:true})};$('#insights').scrollTop=0;$('#close-detail').onclick=()=>{if(selectedLayer)selectedLayer.setStyle(cellStyle(g));selectedLayer=null;state.selected=null;insights()};if(focus||matchMedia('(max-width:740px)').matches){$('#insights').scrollIntoView({block:'nearest'});$('.detail-title').focus({preventScroll:true})}return {gridId:id,locality:g.Area_Name,priority:g.Final_Cooling_Priority,medianLST:g.Final_Median_LST,reliability:g.Planning_Reliability,scenarioTrees:g.Approx_Trees_To_Plant}}
function setupMap(){if(!window.L){document.querySelectorAll('.map-actions button').forEach(b=>b.disabled=true);$('#map').innerHTML='<div class="error-state">The map library could not load. You can still explore all cells in the results table below.</div>'}else{map=L.map('map',{preferCanvas:true,zoomSnap:.25,zoomControl:false,scrollWheelZoom:true}).fitBounds(gridBounds(data.grid_data),{padding:[18,18]});const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);layerGroup=L.featureGroup().addTo(map);let tileErrors=0;const tileNotice=L.control({position:'bottomleft'});tileNotice.onAdd=()=>{const n=L.DomUtil.create('div','tile-status');n.textContent='Basemap unavailable. Research grid remains visible.';return n};tiles.on('tileerror',()=>{if(++tileErrors===3)tileNotice.addTo(map)});tiles.on('tileload',()=>{tileErrors=0;tileNotice.remove()});const fit=L.control({position:'topright'});fit.onAdd=()=>{const b=L.DomUtil.create('button','map-tool');b.textContent='Fit study area';b.onclick=()=>map.fitBounds(gridBounds(data.grid_data),{padding:[18,18],animate:false});L.DomEvent.disableClickPropagation(b);return b};fit.addTo(map);L.control.scale({imperial:false}).addTo(map);$('#zoom-in').onclick=()=>map.zoomIn();$('#zoom-out').onclick=()=>map.zoomOut();$('#fit-results').onclick=()=>{if(filtered.length)map.fitBounds(gridBounds(filtered),{padding:[22,22],maxZoom:13,animate:false})};const updateZoom=()=>{$('#zoom-in').disabled=map.getZoom()>=map.getMaxZoom();$('#zoom-out').disabled=map.getZoom()<=map.getMinZoom()};map.on('zoomend',updateZoom);updateZoom();new ResizeObserver(()=>map.invalidateSize({pan:false})).observe($('#map'))}$('#toggle-filters').onclick=()=>{const b=$('#toggle-filters');const open=b.getAttribute('aria-expanded')!=='true';b.setAttribute('aria-expanded',String(open));b.textContent=open?'Fewer filters':'More filters'};let searchTimer;$('#search').addEventListener('input',e=>{state.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>updateFilters(),180)});$('#reliability').onchange=e=>{state.reliability=e.target.value;updateFilters()};$('#source').onchange=e=>{state.source=e.target.value;updateFilters()};document.querySelectorAll('[data-priority]').forEach(b=>b.onclick=()=>{state.priority=b.dataset.priority;updateFilters(false)});$('#reset').onclick=()=>{Object.assign(state,{query:'',priority:'All',reliability:'All',source:'All',cluster:null});$('#search').value='';$('#reliability').value='All';$('#source').value='All';$('#cluster-context').innerHTML='';history.replaceState(null,'',location.pathname);updateFilters()};const cluster=Number(new URLSearchParams(location.search).get('cluster'));const c=data.hotspot_clusters.find(c=>c.Cluster_ID===cluster);if(c){state.cluster=cluster;$('#cluster-context').innerHTML=`<div class="data-note" style="margin:0 0 20px"><span>Cluster #${c.Cluster_ID} · <strong>${esc(c.Dominant_Locality)}</strong> · ${c.Total_Cells} connected cells. Reset filters to return to the whole study.</span></div>`}updateFilters();}
function registerTools(){
  $('#priority-select').onchange=e=>{state.priority=e.target.value;updateFilters(false)};
  $('#reset').addEventListener('click',()=>{$('#priority-select').value='All'});
  const context=document.modelContext;if(!context?.registerTool)return;
  const lifecycle=new AbortController();
  const tools=[{
    name:'filter_heat_grid',title:'Filter the heat grid',
    description:'Set the visible map filters and return matching counts. Unspecified filters reset to All; cluster selection clears.',
    inputSchema:{type:'object',properties:{query:{type:'string'},priority:{type:'string',enum:['All',...priorities]},reliability:{type:'string',enum:['All','Strong','Moderate','Limited','Model Only']},source:{type:'string',enum:['All','Reliable Multi-Date Observation','Limited Observation + V5','V5 Prediction Only']}},additionalProperties:false},
    annotations:{readOnlyHint:false,untrustedContentHint:true},
    execute(input){
      if(!input||typeof input!=='object'||Array.isArray(input))throw new Error('Expected a filter object');
      const next={query:'',priority:'All',reliability:'All',source:'All',...input};
      if(Object.keys(input).some(k=>!['query','priority','reliability','source'].includes(k))||typeof next.query!=='string'||!['All',...priorities].includes(next.priority)||!['All','Strong','Moderate','Limited','Model Only'].includes(next.reliability)||!['All','Reliable Multi-Date Observation','Limited Observation + V5','V5 Prediction Only'].includes(next.source))throw new Error('Invalid filter value');
      Object.assign(state,next,{cluster:null});
      $('#search').value=next.query;$('#reliability').value=next.reliability;$('#source').value=next.source;$('#priority-select').value=next.priority;
      $('#cluster-context').innerHTML='';history.replaceState(null,'',location.pathname);updateFilters();
      return {matchingCells:filtered.length,highPriorityCells:filtered.filter(g=>['High','Very High'].includes(g.Final_Cooling_Priority)).length};
    }
  },{
    name:'inspect_heat_cell',title:'Inspect a heat grid cell',
    description:'Select a cell from the current filtered results and display its temperature, evidence and cooling recommendation.',
    inputSchema:{type:'object',properties:{gridId:{type:'string'}},required:['gridId'],additionalProperties:false},
    annotations:{readOnlyHint:false,untrustedContentHint:true},
    execute(input){if(!input||typeof input.gridId!=='string'||Object.keys(input).some(k=>k!=='gridId'))throw new Error('Provide only a gridId string');return selectCell(input.gridId,true)}
  }];
  for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
async function start(){try{const names=['project_summary','priority_summary',...(page==='overview'||page==='map'?['grid_data','hotspot_clusters','cluster_membership','cell_indicators']:page==='hotspots'?['hotspot_clusters']:page==='methodology'?['model_metrics']:[])];const result=await Promise.all(names.map(async n=>{const response=await fetch(`data/${n==='grid_data'?'grid_data.min':n}.json`);if(!response.ok)throw new Error(n);return [n,await response.json()]}));data=Object.fromEntries(result);const content=contentPages(data,{number,esc,badge,heading,note});if(page==='overview'||page==='map'){$('#main').innerHTML=overview();setupMap();registerTools()}else if(page==='hotspots'){$('#main').innerHTML=content.hotspots();content.renderClusters();['cluster-search','cluster-sort','cluster-limit'].forEach(id=>$('#'+id).addEventListener(id==='cluster-search'?'input':'change',content.renderClusters))}else if(page==='methodology'){$('#main').innerHTML=content.methodology()}else if(page==='about'){$('#main').innerHTML=content.about()}else{throw new Error('Unknown atlas page')}if(location.hash){document.getElementById(location.hash.slice(1))?.scrollIntoView()}}catch(error){$('#main').innerHTML=`<div class="error-state"><h1>The research data could not load.</h1><p>Please check your connection and try again.</p><button onclick="location.reload()">Reload data</button></div>`;console.error('Atlas loading failed:',error)}}
start();
